			// RHEL 6+, Alma, Rocky, Amazon, Fedora 9+:
			// <Version>-<Release>.<Arch> (and <...>+debug for debug packages)
			ver = fmt.Sprintf("%s-%s.%s", pack.Version, pack.Release, pack.Arch)
			if isDebugKernelPackage(pack.Name) {
				ver += "+debug"
			}
		default:
			// RHEL/CentOS/Oracle < 6, Fedora < 9:
			// <Version>-<Release> (and <...>debug for debug packages)
			ver = fmt.Sprintf("%s-%s", pack.Version, pack.Release)
			if isDebugKernelPackage(pack.Name) {
				ver += "debug"
			}
		}
		return true, kernel.Release == ver

